21	      if (session) {
22	        // Process pending referral (best-effort, never blocks navigation)
23	        const storedCode = localStorage.getItem(REFERRAL_STORAGE_KEY);
24	        const storedEmail = localStorage.getItem(`${REFERRAL_STORAGE_KEY}:email`);
25	        if (storedCode && session.user) {
26	          try {
27	            const { data: referrer } = await supabase
28	              .from("profiles")
29	              .select("id")
30	              .eq("referral_code", storedCode)
31	              .single();
32	
33	            if (referrer && referrer.id !== session.user.id) {
34	              await supabase.from("referrals").insert({
35	                referrer_id: referrer.id,
36	                referred_email: storedEmail ?? session.user.email ?? "",
37	                referred_id: session.user.id,
38	                status: "signed_up",
39	              });
40	            }
41	          } catch {
42	            // Silently ignore — invalid code or duplicate insert
43	          } finally {
44	            localStorage.removeItem(REFERRAL_STORAGE_KEY);
45	            localStorage.removeItem(`${REFERRAL_STORAGE_KEY}:email`);
46	          }
47	        }
